import {analyzeMicrodata,validateMicrodata,NON_VALID} from './microdata.mjs';
import {NAMES,COLORS,nationalVotes} from './electoral.mjs';
import {enhanceParameterHelp,helpButton,parameterHelp} from './tooltips.mjs';
const ids=['pp','psoe','vox','sumar','podemos'],fmt=(n,d=1)=>Number(n).toLocaleString('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d});
const el=(tag,text,className)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(className)n.className=className;return n;};
const label=(data,id)=>NAMES[id]||data.labels[id]||id;
function table(headers,rows){const wrap=el('div',null,'table-scroll'),t=el('table'),head=el('thead'),hr=el('tr');for(const h of headers){const th=el('th',h),help=parameterHelp(h)||(/N efectivo/.test(h)?'Tamaño efectivo con los pesos elegidos antes del ajuste de perfiles. Se calcula con la concentración de pesos; no es un margen de error.':/Directa PESO/.test(h)?'Intención directa ponderada con PESO publicado, sobre todos los entrevistados. No es la estimación final del CIS.':/Ajustada/.test(h)?'Porcentaje sobre la base con los pesos y participación elegidos, antes de asignar indecisos.':/Voto válido exploratorio/.test(h)?'Porcentaje sobre candidaturas y blanco después de la regla de indecisos. Excluye abstención, nulos e indecisos sin asignar.':'');if(help)th.append(helpButton(help,h));hr.append(th);}head.append(hr);t.append(head);const body=el('tbody');for(const row of rows){const tr=el('tr');for(const value of row)tr.append(el('td',value));body.append(tr);}t.append(body);wrap.append(t);return wrap;}
function link(text,url){const a=el('a',text);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
export async function initializeMicrodata({official,getEstimate}){
 const root=document.getElementById('microdata'),out=document.getElementById('micro-output'),status=document.getElementById('micro-status');let data;
 try{const r=await fetch('./data/microdata-3577.json');if(!r.ok)throw Error('No se ha podido cargar el estudio ('+r.status+').');data=validateMicrodata(await r.json());}catch(e){status.textContent=e.message;status.className='notice error';return;}
 const $=id=>document.getElementById(id),reference=nationalVotes(official.provinces).shares;
 const baseline=analyzeMicrodata(data,{dimension:'total'});
 const source=el('div',null,'notice'),audit=el('details');audit.append(el('summary','Consultar variables y huella del archivo'),el('p',Object.entries(data.variables).map(([k,v])=>({intent:'Intención',recall:'Recuerdo',turnout:'Probabilidad de votar',sex:'Sexo',age:'Edad',income:'Ingresos del hogar',ideology:'Ideología'}[k])+': '+v).join(' · ')),el('p','SHA-256 del ZIP: '+data.sha256,'small'));
 source.append(el('strong',data.title+' · '+fmt(data.sample,0)+' entrevistas'),el('p','Entrevistas del '+data.fieldworkStart+' al '+data.fieldworkEnd+'. '+data.note),link('Microdatos y libro de códigos ↗',data.sourceUrl),' · ',link('Ficha técnica ↗',data.technicalUrl),' · ',link('Cuestionario ↗',data.questionnaireUrl),audit);$('micro-source').replaceChildren(source);
 for(const [id,text]of Object.entries(data.dimensions))if(id!=='total')$('micro-dimension').append(new Option(text,id));
 function render(){try{
  const dimension=$('micro-dimension').value,basis=$('micro-basis').value,recallStrength=Number($('micro-recall').value),participation=$('micro-participation').value,undecided=$('micro-undecided').value;
  const estimate=getEstimate(),profileTarget=$('micro-view').value==='profile'?Object.fromEntries(ids.map(id=>[id,estimate.values[id]])):null;
  const result=analyzeMicrodata(data,{dimension,basis,recallStrength,participation,undecided,reference,profileTarget});
  status.textContent='Cálculo exploratorio del estudio '+data.study+'. No modifica la Estimación propia ni los escaños. Último campo: '+data.fieldworkEnd+'.';
  const metrics=el('div',null,'metrics');for(const [name,value]of [['Entrevistas originales',fmt(data.sample,0)],['Tamaño efectivo de pesos',fmt(result.effectiveN,0)],['Indecisos antes de repartir',fmt(100*((result.adjusted.undecided||0)+(result.adjusted.noanswer||0))/result.total)+' %']]){const m=el('div',null,'metric');m.append(el('small',name),el('strong',value));metrics.append(m);}out.replaceChildren(metrics);
  out.append(el('p','Cada alternativa conserva como categorías separadas indecisos, abstención, blanco y nulo. Solo la regla de indecisos elegida redistribuye no sabe/no contesta; nunca reparte abstención ni nulos. El porcentaje de voto válido excluye indecisos no asignados, abstención y nulos: cambiar de denominador no los convierte automáticamente en electores decididos.','notice'));
  out.append(el('h3','Comparación con el promedio de sondeos'),table(['Candidatura','Voto válido exploratorio · %','Promedio de sondeos · %','Diferencia · puntos'],ids.map(id=>[label(data,id),fmt(result.national.validPercent[id]||0,2),fmt(estimate.values[id],2),fmt((result.national.validPercent[id]||0)-estimate.values[id],2)])),el('p','El barómetro se entrevistó del '+data.fieldworkStart+' al '+data.fieldworkEnd+'. El promedio utiliza varios institutos y tiene cálculo '+estimate.calculatedAt+'; el último sondeo se publicó el '+estimate.lastPublication+'. No son observaciones del mismo momento. Una diferencia no prueba sesgo ni superioridad. En modo perfiles, la alternativa de esta tabla conserva su cálculo independiente: solo se ajustan los desgloses.','small muted'));
  out.append(el('h3','Respuestas directas y estimación exploratoria'),table(['Respuesta','Entrevistas','Directa PESO · % encuesta','Ajustada · % base ponderada','Voto válido exploratorio · %'],Object.keys(baseline.raw).sort((a,b)=>baseline.initial[b]-baseline.initial[a]).map(id=>[label(data,id),fmt(baseline.raw[id],0),fmt(100*(baseline.initial[id]||0)/baseline.initialTotal,2),fmt(100*(result.adjusted[id]||0)/result.total,2),NON_VALID.has(id)?'No incluido':fmt(result.national.validPercent[id]||0,2)])));
  out.append(el('p','La columna ajustada se calcula antes de asignar indecisos. La última incorpora la regla elegida y expresa porcentajes sobre las respuestas que el escenario trata como voto válido, incluidos blancos. Es una alternativa de análisis sin calibración electoral acreditada.','small muted'));
  if(profileTarget)out.append(el('p','PERFILES AJUSTADOS AL PROMEDIO: el total nacional de PP, PSOE, Vox, Sumar y Podemos se impone con el promedio de la app ('+estimate.calculatedAt+'), renormalizado solo entre estas cinco candidaturas. Cada fila muestra la distribución dentro de ellas. No incluye partidos territoriales ni blanco, y no es una estimación nacional independiente.','notice'));
  out.append(el('h3',profileTarget?'Perfiles compatibles con el promedio · cinco candidaturas':'Desglose de la alternativa · voto válido'),el('p','N es el número original de entrevistas del grupo; N efectivo refleja concentración de pesos antes del ajuste de perfiles. Un número grande no elimina errores de recuerdo, selección o cuestionario. Los grupos con menos de 30 entrevistas o N efectivo menor de 30 no muestran porcentajes.','small muted'),table(['Grupo','N entrevistas','N efectivo',...ids.map(id=>label(data,id))],result.profiles.map(g=>[data.dimensions[dimension]==='Recuerdo de voto 2023'?label(data,g.group):g.group,fmt(g.n,0),fmt(g.effectiveN,0),...ids.map(id=>g.n<30||g.effectiveN<30?'Base insuficiente':fmt((profileTarget?g.profilePercent:g.validPercent)[id]||0,1)+' %')])));
  const bars=el('div',null,'micro-profile-bars');for(const g of result.profiles){if(g.n<30||g.effectiveN<30)continue;const card=el('div',null,'micro-profile-row');card.append(el('strong',dimension==='recall'?label(data,g.group):g.group));for(const id of ids){const value=(profileTarget?g.profilePercent:g.validPercent)[id]||0,line=el('div',null,'micro-bar-line'),track=el('span',null,'micro-bar-track'),fill=el('span');fill.style.width=value+'%';fill.style.background=COLORS[id];track.append(fill);line.append(el('span',label(data,id)),track,el('span',fmt(value)+' %'));card.append(line);}bars.append(card);}out.append(bars);
  out.append(el('h3','Recuerdo de 2023 → intención declarada actual'),el('p','Esta tabla cruza respuestas de una misma entrevista. No sigue a las personas desde 2023: el voto anterior es un recuerdo declarado. Las filas suman 100 % incluyendo respuestas fuera de las cinco candidaturas. No se aplica aquí la redistribución de indecisos.','small muted'),table(['Recuerdo','N',...ids.map(id=>label(data,id)),'Indecisos','No votaría','Otras respuestas'],result.transitions.map(g=>[label(data,g.group),g.n,...ids.map(id=>g.n<30||g.effectiveN<30?'Base insuficiente':fmt(g.percent[id]||0)+' %'),g.n<30||g.effectiveN<30?'—':fmt((g.percent.undecided||0)+(g.percent.noanswer||0))+' %',g.n<30||g.effectiveN<30?'—':fmt(g.percent.abstention||0)+' %',g.n<30||g.effectiveN<30?'—':fmt(100-ids.reduce((s,id)=>s+(g.percent[id]||0),0)-(g.percent.undecided||0)-(g.percent.noanswer||0)-(g.percent.abstention||0))+' %'])));
  out.append(el('h3','Auditar el ajuste por recuerdo'),el('p','La referencia es el resultado de 2023 entre candidaturas comparables. El ajuste solo afecta a quienes recuerdan esos partidos. No ajusta la abstención, los nuevos electores ni la falta de recuerdo a una distribución poblacional inventada. Los factores se limitan entre 0,25 y 4; ese límite puede impedir alcanzar exactamente la referencia.','small muted'),table(['Recuerdo','Factor aplicado'],Object.entries(result.recallFactors).map(([id,v])=>[label(data,id),fmt(v,3)])),el('p','Participación declarada: '+(participation==='declared'?'multiplica el peso por PROBVOTO/10; '+result.unknownTurnout+' respuestas sin probabilidad válida quedan con peso cero. Es una hipótesis lineal, no una probabilidad calibrada.':'no se utiliza para modificar pesos.')+' '+(result.clipped.length?'Factores limitados: '+result.clipped.map(id=>label(data,id)).join(', ')+'.':''),'small muted'));
  const download=$('micro-export');download.onclick=()=>{const blob=new Blob([JSON.stringify({study:data.study,sourceUrl:data.sourceUrl,sha256:data.sha256,reference,result,interpretation:'Exploración no calibrada; no modifica promedio ni escaños.'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='microdatos-cis-'+data.study+'-escenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  enhanceParameterHelp(root);
 }catch(e){status.textContent=e.message;status.className='notice error';}}
 try{const response=await fetch('./data/microdata-validation.json');if(!response.ok)throw Error('La comprobación histórica no está disponible.');const check=await response.json(),box=$('micro-validation');box.replaceChildren(el('p','Estudio '+check.study+' · '+fmt(check.sample,0)+' entrevistas · campo '+check.fieldworkStart+' → '+check.fieldworkEnd+' · elección '+check.election+'.'),table(['Método','PP','PSOE','Vox','Sumar','Error absoluto medio · puntos'],[...check.rows.map(row=>[row.name,...['pp','psoe','vox','sumar'].map(id=>fmt(row.values[id],2)+' %'),fmt(row.mae,3)]),['Resultado oficial',...['pp','psoe','vox','sumar'].map(id=>fmt(check.actual[id],2)+' %'),'—']]),el('p',check.note,'notice'),link('Microdatos preelectorales 2023 ↗',check.sourceUrl),' · ',link('Ficha técnica 2023 ↗',check.technicalUrl),' · ',link('Referencia de recuerdo: resultado 2019 ↗',check.referenceSource),' · ',link('Resultado oficial 2023 ↗',check.actualSource.verificationUrl),el('p','SHA-256 del fichero histórico: '+check.sha256,'small'));
 }catch(e){$('micro-validation').textContent=e.message;}
 root.querySelectorAll('select,input').forEach(input=>input.addEventListener('change',render));$('micro-reset').addEventListener('click',()=>{$('micro-basis').value='published';$('micro-recall').value='0';$('micro-participation').value='none';$('micro-undecided').value='none';$('micro-view').value='independent';$('micro-dimension').value='age';render();});render();return render;
}
